package com.byawasaya.platform.auth;
import java.io.IOException;import java.util.UUID;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import com.fasterxml.jackson.databind.ObjectMapper;import com.byawasaya.platform.business.TenantTableNameResolver;import com.byawasaya.platform.api.ApiError;
/** Enforces membership-level permissions that cannot be represented by the global STORE_STAFF role alone. */
public class TenantStaffPermissionFilter extends OncePerRequestFilter {
 private final JdbcTemplate jdbc;private final TenantTableNameResolver tables;private final ObjectMapper mapper;
 public TenantStaffPermissionFilter(JdbcTemplate jdbc,TenantTableNameResolver tables,ObjectMapper mapper){this.jdbc=jdbc;this.tables=tables;this.mapper=mapper;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{Authentication auth=SecurityContextHolder.getContext().getAuthentication();if(auth!=null&&auth.getDetails() instanceof TokenService.TokenPrincipal p&&"STORE_STAFF".equals(p.role())&&"PATCH".equalsIgnoreCase(req.getMethod())&&req.getRequestURI().matches("/api/merchant/orders/[0-9a-fA-F-]+/status")){String prefix=tables.prefix(p.businessId()).orElse(null);String role=null;if(prefix!=null){try{UUID accountId=jdbc.queryForObject("SELECT id FROM user_accounts WHERE lower(username)=lower(?)",UUID.class,p.username());role=jdbc.queryForObject("SELECT role FROM "+tables.table(prefix,"staffs")+" WHERE account_id=? AND active=true",String.class,accountId);}catch(org.springframework.dao.DataAccessException ignored){role=null;}}if(!"MANAGER".equals(role)){res.setStatus(403);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),new ApiError(java.time.Instant.now(),403,"Insufficient permission","Only tenant managers or owners can change order status.",java.util.Map.of("requiredRole","MANAGER")));return;}}chain.doFilter(req,res);}
}
